begin;
-- Preserve the preview archive and activate a separate public contract.
do $$ declare existing record; begin
 for existing in select conname from pg_constraint where conrelid='public.local_legal_releases'::regclass and contype='c' and pg_get_constraintdef(oid) like '%scope%' loop
  execute format('alter table public.local_legal_releases drop constraint %I',existing.conname);
 end loop;
end $$;
alter table public.local_legal_releases add constraint legal_release_scope check ((content::jsonb)->>'scope' in ('local-preview','public'));
update public.local_legal_releases set is_current=false where is_current;
